<template>
  <div class="qa-app">
    <div class="search-bar">
      <div class="skew-wrapper">
        <input
          v-model="searchText"
          @input="onInputChange"
          @keyup.enter="onSearch"
          placeholder="搜索题目..."
          type="text"
          class="skew-input"
        />
      </div>
      <button @click="onSearch">
        <img src="../assets/icon/1c20a90cd.png" /><span>搜索</span>
      </button>
    </div>
    <div class="qa-list">
      <QuestionBox
        :question="item.question"
        :answer="item.answer"
        :type="item.type"
        :id="item.id"
        v-for="item in filteredQuestions"
        :key="item.id"
      />
      <div v-if="filteredQuestions.length === 0" class="no-result">
        未找到相关题目
      </div>
    </div>
  </div>
</template>

<script>
import { data_qa } from "../assets/data/qa.js";
import QuestionBox from "./QuestionBox.vue";

export default {
  name: "HelloWorld",
  components: {
    QuestionBox,
  },
  data() {
    return {
      searchText: "",
      questions: data_qa,
      filteredQuestions: data_qa,
    };
  },
  methods: {
    onInputChange() {
      this.filterQuestions();
    },
    onSearch() {
      this.filterQuestions();
    },
    filterQuestions() {
      const text = this.searchText.trim().toLowerCase();
      if (!text) {
        this.filteredQuestions = this.questions;
      } else {
        this.filteredQuestions = this.questions.filter((q) =>
          q.question.toLowerCase().includes(text)
        );
      }
    },
  },
};
</script>

